const item = $input.all()[0];
const json = item.json;

let canal = 'dashboard';
let mensagem = '';
let usuario = 'Felipe';
let chat_id = 'dashboard';
let user_id = 6044282195;

if (json.message && (json.message.text || json.message.voice)) {
  canal = 'telegram';
  mensagem = json.message.text || '[audio]';
  chat_id = String(json.message.chat.id);
  user_id = Number(json.message.from?.id || 6044282195);
  usuario = json.message.from?.first_name || 'Felipe';
} else {
  const body = json.body || json;
  canal = body.canal || 'dashboard';
  mensagem = body.mensagem || body.message || body.texto || '';
  usuario = body.usuario || 'Felipe';
  chat_id = String(body.chat_id || body.session_id || 'dashboard');
  user_id = Number(body.user_id || 6044282195);
  if (canal === 'dashboard') user_id = 6044282195;
}

const isCmd = mensagem.startsWith('/');
const parts = mensagem.trim().split(/\s+/);
const cmd = isCmd ? parts[0].toLowerCase() : '';
const args = isCmd ? parts.slice(1) : [];
const session_id = chat_id && chat_id !== 'dashboard' ? chat_id : 'general';

return [{ json: { canal, mensagem, usuario, chat_id, user_id, is_command: isCmd, cmd, args, ts: new Date().toISOString(), session_id } }];

