const rows = $input.all().map(i => i.json);
const pend = rows.filter(r => r.status === 'PENDENTE').length;
const linhas = rows.map(r => `#${r.id} • ${r.status} • ${String(r.pedido).slice(0,50)}`);
const txt = ['🎖️ *GENERAL — Status*','',`📋 Pendentes: ${pend}`,'',linhas.length ? linhas.join('\n') : '_Nenhuma tarefa._','','_/ajuda para comandos_'].join('\n');
return [{ json: { txt, chat_id: $('Padronizar Entrada').first().json.chat_id } }];

const args = $('Padronizar Entrada').first().json.args || [];
const id = Number(args[0] || 0);
if (!id) return [{ json: { ok: false, msg: '⚠️ Use: /aprovar 5' } }];
return [{ json: { ok: true, id } }];

const row = $input.first().json;
if (!row.id) return [{ json: { ok: false, txt: '⚠️ Não encontrado.', tem_acao: false, acao: {} } }];
const acao = row.acao || {};
const plano_texto = row.previa || row.pedido || '';
return [{ json: { ok: true, id: row.id, acao, previa: row.previa, pedido: row.pedido, plano_texto, tem_acao: Object.keys(acao).length > 0, txt: `✅ Aprovado #${row.id}! Executando...` } }];

const item = $input.first().json;
const acao = item.acao || {};
const tipo = String(acao.tipo || '').toLowerCase();
const chat_id = $('Padronizar Entrada').first().json.chat_id;
let task = 'ping';
let key = 'whoami';
if (tipo === 'executar_pc' || tipo === 'pc' || tipo === 'rpa') {
  task = 'run_powershell';
  key = acao.comando || acao.key || (Array.isArray(acao.passos) && acao.passos[0]) || acao.passo || 'whoami';
}
if (!key || String(key).trim() === '') key = 'whoami';
const bodyParaWorker = { task, key, chat_id };
return [{ json: { bodyParaWorker, chat_id } }];

const item = $input.first();
const chat_id = $('Padronizar Entrada').first().json.chat_id;
const txt = item.error ? '⚠️ PC não respondeu. Verifica o worker.' : '✅ Concluído!';
return [{ json: { txt, chat_id } }];

const args = $('Padronizar Entrada').first().json.args || [];
const id = Number(args[0] || 0);
if (!id) return [{ json: { ok: false, msg: '⚠️ Use: /cancelar 5' } }];
return [{ json: { ok: true, id } }];

const r = $input.first().json;
const ult = r.ultimo ? new Date(r.ultimo).toLocaleString('pt-BR') : 'Nenhum';
return [{ json: { txt: `📊 *Relatório*

Logs: ${r.total}
Último: ${ult}`, chat_id: $('Padronizar Entrada').first().json.chat_id } }];

const rows = $input.all().map(i => i.json);
if (!rows.length) return [{ json: { txt: '🤖 Nenhum agente ainda. Peça ao General criar um!', chat_id: $('Padronizar Entrada').first().json.chat_id } }];
const linhas = rows.map(r => `${r.ativo ? '🟢' : '🔴'} *${r.nome}*: ${r.objetivo}`);
return [{ json: { txt: '🤖 *Exército*\n\n' + linhas.join('\n'), chat_id: $('Padronizar Entrada').first().json.chat_id } }];

const args = $('Padronizar Entrada').first().json.args || [];
const txt = args.join(' ').trim();
if (!txt) return [{ json: { ok: false, chat_id: $('Padronizar Entrada').first().json.chat_id, msg: '⚠️ Use: /audio Olá Felipe!' } }];
return [{ json: { ok: true, chat_id: $('Padronizar Entrada').first().json.chat_id, txt } }];

const item = $input.first();
if (item.binary) {
  const keys = Object.keys(item.binary);
  const src = keys[0] || 'data';
  if (src !== 'data') { item.binary.data = item.binary[src]; delete item.binary[src]; }
}
return [item];

const items = $input.all();
const agentes = items.map(i => i.json).filter(j => j.nome != null);
const sessaoItem = items.find(i => i.json.estado !== undefined) || items[items.length - 1];
const session_estado = sessaoItem?.json?.estado || '';
const session_agente = sessaoItem?.json?.agente_em_criacao || null;
const catalogo = agentes.length ? agentes.map(a => `- ${a.nome}: ${a.objetivo} | PODE: ${a.pode} | NÃO PODE: ${a.nao_pode} | FERRAMENTAS: ${a.ferramentas}`).join('\n') : 'Nenhum agente criado. Se Felipe pedir criar agente, pergunte: nome, objetivo, pode, não pode, ferramentas.';
const sessaoTexto = session_estado ? `\nESTADO DA ENTREVISTA (criar agente): ${session_estado}. Dados parciais: ${JSON.stringify(session_agente || {})}. Continue de onde parou.` : '';
return [{ json: { catalogo: catalogo + sessaoTexto, mensagem: $('Padronizar Entrada').first().json.mensagem, chat_id: $('Padronizar Entrada').first().json.chat_id } }];

const raw = $input.first().json;
let content = '';
if (typeof raw.output === 'string') content = raw.output;
else if (typeof raw.output === 'object') content = JSON.stringify(raw.output);
else content = raw.content || raw.text || JSON.stringify(raw);
let parsed = {};
try {
  const m = content.match(/\{[\s\S]*\}/);
  parsed = m ? JSON.parse(m[0]) : { resposta: content, precisa_aprovar: false, previa: '', agente_usado: 'general', acao: {} };
} catch(e) {
  parsed = { resposta: content, precisa_aprovar: false, previa: '', agente_usado: 'general', acao: {} };
}
if (!parsed.resposta || parsed.resposta.trim() === '') parsed.resposta = content;
const hasAction = parsed.acao && Object.keys(parsed.acao).length > 0;
const tipo = String(parsed.tipo_acao || parsed.tipo || '').toLowerCase();
const perigoso = ['postar','pagar','apagar','enviar_em_massa','executar_pc','criar_agente','pc','rpa'].includes(tipo);
if (hasAction || perigoso) parsed.precisa_aprovar = true;
const padrao = $('Padronizar Entrada').first().json;
return [{ json: { ...parsed, chat_id: padrao.chat_id, canal: padrao.canal || 'telegram' } }];

const inp = $input.first().json;
const prev = $('Ler Resposta General').first().json;
let openclaw_erro = false;
let openclaw_msg = '';
if (inp.error || inp.message) {
  openclaw_erro = true;
  openclaw_msg = inp.error || inp.message || 'OpenClaw indisponível';
}
return [{ json: { ...prev, openclaw_erro, openclaw_msg } }];

const g = $('Ler Resposta General').first().json;
const padrao = $('Padronizar Entrada').first().json;
const esc = s => String(s ?? '').replace(/'/g, "''");
const pedido_esc = esc(g.resposta);
const previa_esc = esc(g.previa);
const acao = g.acao || {};
const acao_json = JSON.stringify(acao).replace(/'/g, "''");
return [{ json: { chat_id: padrao.chat_id, user_id: padrao.user_id, pedido_esc, previa_esc, acao_json } }];

const row = $input.first().json;
const id = Array.isArray(row) ? row[0]?.id : row.id;
const g = $('Ler Resposta General').first().json;
const txt = [`👀 *PRÉVIA #${id}*`, '', g.previa || g.resposta, '', `✅ /aprovar ${id}`, `❌ /cancelar ${id}`].join('\n');
return [{ json: { txt, chat_id: $('Padronizar Entrada').first().json.chat_id } }];
